begin;
\ir ../fixtures/research.inc
select pg_temp.research_fixture(array['editor']);
\ir ../fixtures/research-authenticate.inc
select lives_ok($$select public.create_research_draft(pg_temp.research_input('editor-created'))$$,'Editor creates complete own draft');
select lives_ok($$select public.create_research_draft(pg_temp.research_input('editor-sponsored')||'{"classification":"SPONSORED"}')$$,'Editor may create disclosed Sponsored draft');
select throws_ok($$select public.create_research_draft(pg_temp.research_input('editor-other-author')||'{"author_id":"10000000-0000-4000-8000-000000000002"}')$$,'42501',null,'Editor cannot choose another accountable author');
select throws_ok($$select public.change_research_classification('10000000-0000-4000-8000-000000000107',1,'PARTNER','Disclosure','Reason')$$,'42501',null,'Editor cannot elevate classification authority');
select throws_ok($$select public.save_research_author('10000000-0000-4000-8000-000000000001','Tampered')$$,'42501',null,'Editor cannot administer bylines');
select is((select count(*)::integer from public.research_token_options()),2,'Editor gets narrow token identity picker');
select is((select count(*)::integer from public.tokens),0,'Picker does not broaden Editor raw registry RLS');
select throws_ok($$delete from public.articles$$,'42501',null,'Editor has no hard delete path');
select lives_ok($$select public.save_research_draft('10000000-0000-4000-8000-000000000107',1,'{"title":"Edited draft"}')$$,'Editor edits draft');
select lives_ok($$select public.transition_research_article('10000000-0000-4000-8000-000000000107',2,'schedule',now()+interval '1 day')$$,'Draft schedules with audit');
select throws_ok($$select public.save_research_draft('10000000-0000-4000-8000-000000000107',3,'{"title":"Live change"}')$$,'55000',null,'Scheduled content is read-only');
select throws_ok($$select public.transition_research_article('10000000-0000-4000-8000-000000000107',3,'publish')$$,'55000',null,'Scheduled content cannot publish before due');
select lives_ok($$select public.transition_research_article('10000000-0000-4000-8000-000000000107',3,'reschedule',now()+interval '2 days')$$,'Reschedule is explicit');
select throws_ok($$select public.transition_research_article('10000000-0000-4000-8000-000000000107',4,'reschedule',now()-interval '1 day')$$,'22023',null,'Past reschedule denied');
select lives_ok($$select public.transition_research_article('10000000-0000-4000-8000-000000000107',4,'unschedule',null,'Review again')$$,'Unschedule returns to draft');
select is((select scheduled_at from public.articles where slug='fixture-own-draft'),null::timestamptz,'Unschedule clears schedule');
select lives_ok($$select public.transition_research_article('10000000-0000-4000-8000-000000000107',5,'publish')$$,'Complete draft explicitly publishes');
create temporary table first_publication as select published_at from public.articles where slug='fixture-own-draft';
select is((select published_revision=revision from public.articles where slug='fixture-own-draft'),true,'Publication marks exactly the committed revision');
select is((select count(*)::integer from public.read_public_research_article('fixture-own-draft')),1,'Explicit publication becomes public');
select throws_ok($$select public.save_research_draft('10000000-0000-4000-8000-000000000107',6,'{"title":"Silent live edit"}')$$,'55000',null,'Published content cannot be silently edited');
select lives_ok($$select public.transition_research_article('10000000-0000-4000-8000-000000000107',6,'archive',null,'Correction')$$,'Published article archives');
select is((select count(*)::integer from public.read_public_research_article('fixture-own-draft')),0,'Archive immediately withdraws projection');
select lives_ok($$select public.transition_research_article('10000000-0000-4000-8000-000000000107',7,'restore',null,'Prepare correction')$$,'Archive restores only to draft');
select throws_ok($$select public.save_research_draft('10000000-0000-4000-8000-000000000107',8,'{"slug":"rewritten-history"}')$$,'55000',null,'Restoration cannot rewrite published slug');
select lives_ok($$select public.save_research_draft('10000000-0000-4000-8000-000000000107',8,'{"title":"Corrected offline"}')$$,'Restored draft can be corrected offline');
select lives_ok($$select public.transition_research_article('10000000-0000-4000-8000-000000000107',9,'publish')$$,'Corrected draft republishes explicitly');
select is((select published_at from public.articles where slug='fixture-own-draft'),(select published_at from first_publication),'Republication preserves first publication time');
select lives_ok($$select public.transition_research_article('10000000-0000-4000-8000-000000000104',1,'publish')$$,'Due scheduled article requires and accepts explicit publication');
select throws_ok($$select public.transition_research_article('10000000-0000-4000-8000-000000000105',1,'publish')$$,'55000',null,'Archived to Published shortcut denied');
select throws_ok($$select public.transition_research_article('10000000-0000-4000-8000-000000000105',1,'archive',null,'Reason')$$,'55000',null,'Repeated archive is not a transition');
select throws_ok($$select public.transition_research_article('10000000-0000-4000-8000-000000000102',1,'restore',null,'Reason')$$,'55000',null,'Draft to restored shortcut denied');
select throws_ok($$select public.transition_research_article('10000000-0000-4000-8000-000000000102',1,'unschedule',null,'Reason')$$,'55000',null,'Unscheduled draft cannot unschedule');
select lives_ok($$select public.transition_research_article('10000000-0000-4000-8000-000000000102',1,'archive',null,'Discard draft')$$,'Draft may archive without destruction');
select lives_ok($$select public.transition_research_article('10000000-0000-4000-8000-000000000102',2,'restore',null,'Recover')$$,'Never-published draft is recoverable');
select lives_ok($$select public.transition_research_article('10000000-0000-4000-8000-000000000103',1,'archive',null,'Cancel schedule')$$,'Scheduled article may archive');
select lives_ok($$select public.transition_research_article('10000000-0000-4000-8000-000000000103',2,'restore',null,'Recover')$$,'Scheduled archive may restore to draft');
select is((select scheduled_at from public.articles where slug='fixture-scheduled'),null::timestamptz,'Restore clears stale schedule');
reset role;
update public.feature_flags set enabled=false where key='research_enabled';
set local role authenticated;
select lives_ok($$select public.save_research_draft('10000000-0000-4000-8000-000000000102',3,'{"title":"Recovery edit"}')$$,'Feature outage does not prevent permitted draft editing');
select throws_ok($$select public.transition_research_article('10000000-0000-4000-8000-000000000102',4,'publish')$$,'55000',null,'Disabled feature blocks publication');
select lives_ok($$select public.transition_research_article('10000000-0000-4000-8000-000000000107',10,'archive',null,'Emergency withdrawal')$$,'Feature outage still permits withdrawal');
reset role;
select ok(not exists(select 1 from public.audit_logs where actor_id<>'10000000-0000-4000-8000-000000000001'),'All Editor audit actors are real caller');
select is((select count(*)::integer from public.audit_logs where action='article.published'),3,'Each actual publication has an audit event');
select * from finish();
rollback;
